const withHolds = inputs.auditedBatches.map((b) => {
  let holdbackAmount = 0;
  if (!b.isCompliant || b.grossDiff > 500) {
    holdbackAmount = Math.round(b.ledgerGross * 0.10);
  }
  return {
    ...b,
    holdbackAmount,
  };
});
return { holdbackBatches: withHolds };
```

