const taxed = inputs.holdbackBatches.map((h) => {
  const pph23OnFee = Math.round(h.gatewayFee * 0.02);
  return {
    ...h,
    pph23Withholding: pph23OnFee,
  };
});
return { taxedSettlement: taxed };
```

--- Cell ID: f05eaff1-c3d5-49ae-bb7c-d004baca5508 ---
